    override fun write(value: FfiBottleneckReport, buf: ByteBuffer) {
            FfiConverterString.write(value.`transferId`, buf)
            FfiConverterString.write(value.`fileName`, buf)
            FfiConverterULong.write(value.`fileSize`, buf)
