sealed class FfiTransferException: kotlin.Exception() {
    
    class Generic(
        
        val `msg`: kotlin.String
        ) : FfiTransferException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiTransferException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiTransferException = FfiConverterTypeFfiTransferError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiTransferError : FfiConverterRustBuffer<FfiTransferException> {
    override fun read(buf: ByteBuffer): FfiTransferException {
        

        return when(buf.getInt()) {
            1 -> FfiTransferException.Generic(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiTransferException): ULong {
        return when(value) {
            is FfiTransferException.Generic -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
        }
    }

    override fun write(value: FfiTransferException, buf: ByteBuffer) {
        when(value) {
            is FfiTransferException.Generic -> {
                buf.putInt(1)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




